import{_ as s,a as r}from"./chunks/section-services.CtQladIJ.js";import{_ as t,c as o,o as i,ae as a}from"./chunks/framework.DBgX5bsf.js";const f=JSON.parse('{"title":"Présentation","description":"","frontmatter":{},"headers":[],"relativePath":"fr/docs/index.md","filePath":"fr/docs/index.md"}'),n={name:"fr/docs/index.md"};function l(u,e,c,d,p,m){return i(),o("div",null,e[0]||(e[0]=[a('<h1 id="presentation" tabindex="-1">Présentation <a class="header-anchor" href="#presentation" aria-label="Permalink to &quot;Présentation&quot;">​</a></h1><p>Ce thème est construit autour du module <a href="https://www.drupal.org/docs/8/core/modules/layout-builder" target="_blank" rel="noreferrer">Layout Builder</a> et propose <strong>plus de 100 mises en page prédéfinies</strong>, vous permettant d&#39;améliorer et de créer de nouvelles pages, sections et layouts (structures de page) facilement.</p><p><strong>Habeuk-event</strong> est un thème compatible avec Drupal 9/10, conçu pour vous aider à construire et personnaliser rapidement votre site Drupal. Si vous débutez dans la création de votre site web, nous vous recommandons vivement d&#39;utiliser ce thème pour sa flexibilité et sa simplicité d&#39;utilisation.</p><hr><h2 id="concepts-cles" tabindex="-1">Concepts Clés <a class="header-anchor" href="#concepts-cles" aria-label="Permalink to &quot;Concepts Clés&quot;">​</a></h2><p>Tout au long de ce guide, nous utiliserons des termes tels que <strong>sections</strong>, <strong>layouts</strong>, <strong>boutons</strong>, et bien d&#39;autres. Il est important de bien comprendre ces concepts dès le départ.</p><h3 id="sections" tabindex="-1">Sections <a class="header-anchor" href="#sections" aria-label="Permalink to &quot;Sections&quot;">​</a></h3><p>Une <strong>section</strong> représente un bloc de contenu conçu pour mettre en avant ou afficher des informations spécifiques. Elle occupe toute la largeur de la page. Par exemple, sur une page d&#39;accueil, vous pourriez avoir plusieurs sections :</p><ul><li>Une section présentant des résumés de différents services.</li><li>Une section affichant les derniers articles de blog.</li><li>Une section contenant un formulaire de contact.</li><li>Et ainsi de suite.</li></ul><h4 id="exemple-1-resumes-des-articles-de-blog" tabindex="-1">Exemple 1 : Résumés des articles de blog <a class="header-anchor" href="#exemple-1-resumes-des-articles-de-blog" aria-label="Permalink to &quot;Exemple 1 : Résumés des articles de blog&quot;">​</a></h4><figure class="figure"><img src="'+s+'" class="figure-img img-fluid rounded" alt="Section des résumés des articles de blog"><figcaption class="figure-caption">Une section affichant les résumés des derniers articles de blog.</figcaption></figure><h4 id="exemple-2-resumes-des-services" tabindex="-1">Exemple 2 : Résumés des services <a class="header-anchor" href="#exemple-2-resumes-des-services" aria-label="Permalink to &quot;Exemple 2 : Résumés des services&quot;">​</a></h4><figure class="figure"><img src="'+r+'" class="figure-img img-fluid rounded" alt="Section des résumés des services"><figcaption class="figure-caption">Une section mettant en avant les résumés des services proposés.</figcaption></figure><hr><h3 id="layouts-mises-en-page" tabindex="-1">Layouts (Mises en page) <a class="header-anchor" href="#layouts-mises-en-page" aria-label="Permalink to &quot;Layouts (Mises en page)&quot;">​</a></h3><p>Un <strong>layout</strong> fait référence à l&#39;agencement graphique d&#39;éléments tels que les titres, descriptions, images, icônes, etc. Dans Drupal, un layout peut aller d&#39;un élément simple comme un bouton à une structure complexe comme une <strong>section</strong> ou un <strong>diaporama (slider)</strong>.</p><h4 id="caracteristiques-des-layouts" tabindex="-1">Caractéristiques des Layouts : <a class="header-anchor" href="#caracteristiques-des-layouts" aria-label="Permalink to &quot;Caractéristiques des Layouts :&quot;">​</a></h4><ul><li><strong>Flexibilité</strong> : Réorganisez facilement les éléments pour répondre à vos besoins de conception.</li><li><strong>Réutilisabilité</strong> : Enregistrez et réutilisez les layouts sur plusieurs pages.</li><li><strong>Personnalisation</strong> : Adaptez les layouts pour qu&#39;ils correspondent à l&#39;identité de votre marque.</li></ul><hr><h2 id="pourquoi-choisir-habeuk-event" tabindex="-1">Pourquoi choisir Habeuk-event ? <a class="header-anchor" href="#pourquoi-choisir-habeuk-event" aria-label="Permalink to &quot;Pourquoi choisir Habeuk-event ?&quot;">​</a></h2><ul><li><strong>Plus de 100 layouts prédéfinis</strong> : Démarrez rapidement la conception de votre site avec une grande variété de mises en page.</li><li><strong>Compatibilité Drupal 9/10</strong> : Conçu pour fonctionner parfaitement avec les dernières versions de Drupal.</li><li><strong>Convivial</strong> : Idéal pour les débutants comme pour les développeurs expérimentés.</li><li><strong>Personnalisable</strong> : Adaptez facilement les layouts et sections pour répondre à vos besoins spécifiques.</li></ul><hr><h2 id="pour-commencer" tabindex="-1">Pour commencer <a class="header-anchor" href="#pour-commencer" aria-label="Permalink to &quot;Pour commencer&quot;">​</a></h2><p>Pour commencer à utiliser le thème Habeuk-event :</p><ol><li>Installez le thème via l&#39;interface d&#39;administration de Drupal.</li><li>Explorez le <strong>Layout Builder</strong> pour commencer à créer des pages et des sections.</li><li>Personnalisez les layouts pour qu&#39;ils correspondent aux exigences de votre site.</li></ol><p>Pour des instructions détaillées, consultez la <a href="#">documentation de Habeuk-event</a>.</p><hr><h2 id="support-et-ressources" tabindex="-1">Support et ressources <a class="header-anchor" href="#support-et-ressources" aria-label="Permalink to &quot;Support et ressources&quot;">​</a></h2><p>Si vous rencontrez des problèmes ou avez des questions, veuillez consulter la <a href="#">documentation officielle</a> ou contacter notre équipe de support.</p>',29)]))}const b=t(n,[["render",l]]);export{f as __pageData,b as default};
